SELECT p.gender, percent_rank() OVER (PARTITION BY p.gender ORDER BY m.medication_complexity_score) AS percentile_rank, m.medication_complexity_score, AVG(s.length_of_stay) AS average_length_of_stay, CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN s.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT s.subject_id), 0) AS in_hospital_mortality_rate, CAST(COUNT(DISTINCT CASE WHEN s.subject_id IN (SELECT subject_id FROM transfers) THEN s.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT s.subject_id), 0) AS readmission_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN emar e ON a.hadm_id = e.hadm_id JOIN (SELECT subject_id, COUNT(*) AS medication_count, SUM(CASE WHEN dose_given IS NOT NULL THEN 1 ELSE 0 END) AS medication_complexity_score FROM emar_detail GROUP BY subject_id) m ON a.hadm_id = m.subject_id JOIN icustays s ON a.subject_id = s.subject_id WHERE EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 43 AND 53 GROUP BY p.gender, percentile_rank, medication_complexity_score, average_length_of_stay, in_hospital_mortality_rate, readmission_rate ORDER BY p.gender, percentile_rank NULLS LAST;